INSERT INTO films (id, title, label, provenance, created_at) VALUES
    ('demo-feature', 'TITANIC', 'LOCAL DEMO · TITANIC', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:00', 3, 'UTC'));
INSERT INTO revisions (id, film_id, revision_number, label, changed_scene, change_summary, before_text, after_text, provenance, created_at) VALUES
    ('rev-05', 'demo-feature', 5, 'V5 · TITANIC / COLLISION', 'SC 17 · ICEBERG COLLISION', 'A fictional revision moves the collision beat into a fully timed Titanic storyboard. [clio_demo_version=titanic-v1]', 'The ship holds course in calm water; passengers remain unaware of the iceberg ahead.', 'The ship strikes the iceberg; every later escape and survival beat inherits the impact.', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:01', 3, 'UTC'));
INSERT INTO pipeline_stages (id, sequence, name, description, provenance) VALUES
    ('30101010-1010-1010-1010-101010101001', 1, 'Script', 'Complete timed Titanic screenplay scenes, narration, and child beats from opening salvage to final memory.', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation","storyboard_version":"titanic-v1"}');
INSERT INTO graph_nodes (id, kind, label, sequence, stage_name, status, film_id, revision_id, scene_number, heading, script_text, start_seconds, end_seconds, duration_seconds, metadata, provenance, created_at, beat_number, parent_scene_id, narration_text) VALUES
    ('40101010-1010-1010-1010-101010101001', 'script', 'V5 · TITANIC', 0, 'Script', 'breaking', 'demo-feature', 'rev-05', NULL, NULL, 'Lookouts spot an iceberg, the bridge orders a turn, and Titanic strikes the ice beneath the calm surface.', NULL, NULL, NULL, '{"role":"revision_source","dataset":"LOCAL DEMO · TITANIC","before_text":"The ship holds course in calm water; passengers remain unaware of the iceberg ahead.","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:00', 3, 'UTC'), NULL, NULL, NULL),
    ('40101010-1010-1010-1010-000000001001', 'scene', 'EXT. NORTH ATLANTIC / WRECK SITE — DAY (1996)', 1, 'Script', 'understood', 'demo-feature', 'rev-05', '01', 'EXT. NORTH ATLANTIC / WRECK SITE — DAY (1996)', 'A deep-sea expedition maps the wreck and finds a portrait that brings an elderly witness back to 1912.', 0, 300, 300, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:10', 3, 'UTC'), NULL, NULL, 'NARRATOR: The search begins where memory went down.'),
    ('40101010-1010-1010-1010-000000001002', 'scene', 'INT. KELDYSH — DAY (1996)', 2, 'Script', 'understood', 'demo-feature', 'rev-05', '02', 'INT. KELDYSH — DAY (1996)', 'On the research ship, Rose identifies herself and turns a treasure hunt into a complete memory of Titanic.', 300, 540, 240, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:11', 3, 'UTC'), NULL, NULL, 'ROSE: You are looking for a jewel; I remember a life.'),
    ('40101010-1010-1010-1010-000000001003', 'scene', 'INT. ROSE’S BEDROOM — NIGHT (1912)', 3, 'Script', 'understood', 'demo-feature', 'rev-05', '03', 'INT. ROSE’S BEDROOM — NIGHT (1912)', 'Young Rose prepares for the maiden voyage while family duty turns her future into an arrangement.', 540, 810, 270, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:12', 3, 'UTC'), NULL, NULL, 'NARRATOR: Before the ship moves, a life is already being steered.'),
    ('40101010-1010-1010-1010-000000001004', 'scene', 'EXT. SOUTHAMPTON DOCKS — DAY (1912)', 4, 'Script', 'understood', 'demo-feature', 'rev-05', '04', 'EXT. SOUTHAMPTON DOCKS — DAY (1912)', 'Passengers crowd the quay as Titanic prepares to sail; Jack wins a last-minute passage and boards with steerage.', 810, 1170, 360, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:13', 3, 'UTC'), NULL, NULL, 'NARRATOR: A city gathers around one impossible machine.'),
    ('40101010-1010-1010-1010-000000001005', 'scene', 'INT. THIRD-CLASS CABIN / DECK — DAY', 5, 'Script', 'understood', 'demo-feature', 'rev-05', '05', 'INT. THIRD-CLASS CABIN / DECK — DAY', 'Jack finds friends among the steerage passengers and begins drawing the people and machinery around him.', 1170, 1560, 390, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:14', 3, 'UTC'), NULL, NULL, 'NARRATOR: Below the polished rooms, the voyage is loud, close, and alive.'),
    ('40101010-1010-1010-1010-000000001006', 'scene', 'INT. FIRST-CLASS SUITE — DAY', 6, 'Script', 'understood', 'demo-feature', 'rev-05', '06', 'INT. FIRST-CLASS SUITE — DAY', 'Rose is dressed for a first-class life while Ruth and Cal turn the voyage into a public rehearsal for marriage.', 1560, 1980, 420, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:15', 3, 'UTC'), NULL, NULL, 'NARRATOR: Upstairs, comfort hides the pressure it was built to protect.'),
    ('40101010-1010-1010-1010-000000001007', 'scene', 'INT. FIRST-CLASS DINING SALON — EVENING', 7, 'Script', 'understood', 'demo-feature', 'rev-05', '07', 'INT. FIRST-CLASS DINING SALON — EVENING', 'The first-class table celebrates speed and status while Rose performs the role everyone has chosen for her.', 1980, 2400, 420, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:16', 3, 'UTC'), NULL, NULL, 'NARRATOR: The chandeliers hold a dinner above a dangerous silence.'),
    ('40101010-1010-1010-1010-000000001008', 'scene', 'EXT. STERN — NIGHT', 8, 'Script', 'understood', 'demo-feature', 'rev-05', '08', 'EXT. STERN — NIGHT', 'Rose walks to the stern intending to end her life; Jack finds her and gives her a reason to climb back.', 2400, 2820, 420, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:17', 3, 'UTC'), NULL, NULL, 'NARRATOR: At the edge of the ship, one choice can change the entire map.'),
    ('40101010-1010-1010-1010-000000001009', 'scene', 'INT. FIRST-CLASS CORRIDOR — NIGHT', 9, 'Script', 'understood', 'demo-feature', 'rev-05', '09', 'INT. FIRST-CLASS CORRIDOR — NIGHT', 'The rescue becomes a social transaction as Cal, Lovejoy, and Rose decide what Jack’s presence will mean.', 2820, 3240, 420, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:18', 3, 'UTC'), NULL, NULL, 'NARRATOR: A private rescue is rewritten by the people who witnessed it.'),
    ('40101010-1010-1010-1010-000000001010', 'scene', 'INT. FIRST-CLASS DINING SALON — NIGHT', 10, 'Script', 'understood', 'demo-feature', 'rev-05', '10', 'INT. FIRST-CLASS DINING SALON — NIGHT', 'Jack joins Cal’s table and answers the class test with a life shaped by travel, work, and observation.', 3240, 3720, 480, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:19', 3, 'UTC'), NULL, NULL, 'NARRATOR: The room asks Jack to prove he deserves to breathe its air.'),
    ('40101010-1010-1010-1010-000000001011', 'scene', 'INT. GRAND STAIRCASE / PROMENADE — NIGHT', 11, 'Script', 'understood', 'demo-feature', 'rev-05', '11', 'INT. GRAND STAIRCASE / PROMENADE — NIGHT', 'Rose slips away from the formal party and meets Jack between the grand staircase and the open deck.', 3720, 4200, 480, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:20', 3, 'UTC'), NULL, NULL, 'NARRATOR: The ship has two nights, and Rose starts walking between them.'),
    ('40101010-1010-1010-1010-000000001012', 'scene', 'INT. THIRD-CLASS PARTY — NIGHT', 12, 'Script', 'understood', 'demo-feature', 'rev-05', '12', 'INT. THIRD-CLASS PARTY — NIGHT', 'Rose joins the steerage celebration, finding movement, laughter, and a version of herself that Cal cannot choreograph.', 4200, 4680, 480, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:21', 3, 'UTC'), NULL, NULL, 'NARRATOR: In the lower rooms, joy does not ask for a ticket.'),
    ('40101010-1010-1010-1010-000000001013', 'scene', 'EXT. BOW — NIGHT', 13, 'Script', 'understood', 'demo-feature', 'rev-05', '13', 'EXT. BOW — NIGHT', 'Jack brings Rose to the bow, where the horizon, wind, and their first kiss give her a new sense of scale.', 4680, 5160, 480, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:22', 3, 'UTC'), NULL, NULL, 'NARRATOR: The front of the ship feels like the front of a life.'),
    ('40101010-1010-1010-1010-000000001014', 'scene', 'INT. ROSE’S SUITE — DAY', 14, 'Script', 'understood', 'demo-feature', 'rev-05', '14', 'INT. ROSE’S SUITE — DAY', 'Rose invites Jack to draw her wearing the Heart of the Ocean, turning a stolen hour into a record of her choice.', 5160, 5640, 480, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:23', 3, 'UTC'), NULL, NULL, 'NARRATOR: The portrait is commissioned by a woman choosing how she will be seen.'),
    ('40101010-1010-1010-1010-000000001015', 'scene', 'INT. ROSE’S SUITE / CORRIDOR — NIGHT', 15, 'Script', 'understood', 'demo-feature', 'rev-05', '15', 'INT. ROSE’S SUITE / CORRIDOR — NIGHT', 'Cal discovers the portrait and sends Lovejoy after Rose and Jack as the romance becomes an open threat.', 5640, 6120, 480, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:24', 3, 'UTC'), NULL, NULL, 'NARRATOR: The room that held a secret becomes the room that exposes it.'),
    ('40101010-1010-1010-1010-000000001016', 'scene', 'INT. CARGO HOLD — NIGHT', 16, 'Script', 'understood', 'demo-feature', 'rev-05', '16', 'INT. CARGO HOLD — NIGHT', 'Rose and Jack hide among the automobiles, choosing intimacy while Lovejoy searches the dark hold around them.', 6120, 6600, 480, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:25', 3, 'UTC'), NULL, NULL, 'NARRATOR: Beneath the ballroom, metal and breath become a private room.'),
    ('40101010-1010-1010-1010-000000001017', 'scene', 'INT. BRIDGE / LOOKOUT — NIGHT', 17, 'Script', 'breaking', 'demo-feature', 'rev-05', '17', 'INT. BRIDGE / LOOKOUT — NIGHT', 'Lookouts spot an iceberg, the bridge orders a turn, and Titanic strikes the ice beneath the calm surface.', 6600, 7110, 510, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:26', 3, 'UTC'), NULL, NULL, 'NARRATOR: The revision point is not the collision alone; it is every line that now has to move.'),
    ('40101010-1010-1010-1010-000000001018', 'scene', 'INT. LOWER DECKS / STEERAGE CORRIDORS — NIGHT', 18, 'Script', 'pending', 'demo-feature', 'rev-05', '18', 'INT. LOWER DECKS / STEERAGE CORRIDORS — NIGHT', 'Water enters the lower decks while officers calculate the damage and steerage passengers meet locked gates and confusing routes.', 7110, 7620, 510, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:27', 3, 'UTC'), NULL, NULL, 'NARRATOR: The first people to feel the sinking are the people furthest from the boats.'),
    ('40101010-1010-1010-1010-000000001019', 'scene', 'INT. FIRST-CLASS SUITE / CORRIDOR — NIGHT', 19, 'Script', 'pending', 'demo-feature', 'rev-05', '19', 'INT. FIRST-CLASS SUITE / CORRIDOR — NIGHT', 'Rose and Jack return to the changing ship; Cal discovers the diamond and frames Jack before the evacuation.', 7620, 8130, 510, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:28', 3, 'UTC'), NULL, NULL, 'NARRATOR: The old order keeps fighting even after the ship proves it cannot protect anyone.'),
    ('40101010-1010-1010-1010-000000001020', 'scene', 'EXT. BOAT DECK / GRAND STAIRCASE — NIGHT', 20, 'Script', 'pending', 'demo-feature', 'rev-05', '20', 'EXT. BOAT DECK / GRAND STAIRCASE — NIGHT', 'Lifeboats begin launching as Rose is separated from Jack, then refuses safety when she realizes he is still trapped.', 8130, 8670, 540, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:29', 3, 'UTC'), NULL, NULL, 'NARRATOR: A seat in a boat is offered as if survival can be assigned.'),
    ('40101010-1010-1010-1010-000000001021', 'scene', 'INT. FLOODED MASTER-AT-ARMS OFFICE — NIGHT', 21, 'Script', 'pending', 'demo-feature', 'rev-05', '21', 'INT. FLOODED MASTER-AT-ARMS OFFICE — NIGHT', 'Rose finds Jack handcuffed in a flooding office, breaks the chain, and leads them through the rising corridors.', 8670, 9210, 540, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:30', 3, 'UTC'), NULL, NULL, 'NARRATOR: The rescue reverses direction; the person saved becomes the person who saves.'),
    ('40101010-1010-1010-1010-000000001022', 'scene', 'EXT. BOAT DECK / COLLAPSING SHIP — NIGHT', 22, 'Script', 'pending', 'demo-feature', 'rev-05', '22', 'EXT. BOAT DECK / COLLAPSING SHIP — NIGHT', 'Rose and Jack move through the evacuation as Cal fires after them and Titanic’s stern begins to rise.', 9210, 9750, 540, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:31', 3, 'UTC'), NULL, NULL, 'NARRATOR: The last open deck is shrinking beneath every choice.'),
    ('40101010-1010-1010-1010-000000001023', 'scene', 'INT. GRAND STAIRCASE / EXT. STERN — NIGHT', 23, 'Script', 'pending', 'demo-feature', 'rev-05', '23', 'INT. GRAND STAIRCASE / EXT. STERN — NIGHT', 'The hull tears apart, passengers slide into the sea, and Rose and Jack cling to the stern as Titanic disappears beneath them.', 9750, 10230, 480, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:32', 3, 'UTC'), NULL, NULL, 'NARRATOR: The ship’s final movement carries everyone beyond the old map.'),
    ('40101010-1010-1010-1010-000000001024', 'scene', 'EXT. NORTH ATLANTIC — NIGHT', 24, 'Script', 'pending', 'demo-feature', 'rev-05', '24', 'EXT. NORTH ATLANTIC — NIGHT', 'In the freezing water, Rose and Jack share a floating panel, promise a future, and wait for a lifeboat to return.', 10230, 10680, 450, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:33', 3, 'UTC'), NULL, NULL, 'NARRATOR: Survival becomes a space barely large enough for one body and one promise.'),
    ('40101010-1010-1010-1010-000000001025', 'scene', 'EXT. CARPATHIA / NEW YORK / ROSE’S MEMORY — DAWN/NIGHT', 25, 'Script', 'resolved', 'demo-feature', 'rev-05', '25', 'EXT. CARPATHIA / NEW YORK / ROSE’S MEMORY — DAWN/NIGHT', 'Rose is rescued, chooses her own name, survives into old age, and returns the diamond to the ocean before finding Titanic alive in memory.', 10680, 11700, 1020, '{"role":"scene","dataset":"LOCAL DEMO · TITANIC","child_count":5,"storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 00:00:34', 3, 'UTC'), NULL, NULL, 'NARRATOR: The ending is not the sinking; it is the life Rose carries away.');
INSERT INTO graph_nodes (id, kind, label, sequence, stage_name, status, film_id, revision_id, scene_number, beat_number, parent_scene_id, heading, script_text, narration_text, start_seconds, end_seconds, duration_seconds, metadata, provenance, created_at) VALUES
    ('41101010-1010-1010-1010-000100000001', 'beat', 'SONAR GRID', 6, 'Script', 'understood', 'demo-feature', 'rev-05', '01', 1, '40101010-1010-1010-1010-000000001001', 'SONAR GRID', 'The research vessel sweeps a sonar grid across the seabed.', 'NARRATOR: Steel leaves a shadow long after voices leave.', 0, 60, 60, '{"role":"beat","dataset":"LOCAL DEMO · TITANIC","parent_scene":"01","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 01:00:00', 3, 'UTC')),
    ('41101010-1010-1010-1010-000100000002', 'beat', 'DESCENT', 7, 'Script', 'understood', 'demo-feature', 'rev-05', '01', 2, '40101010-1010-1010-1010-000000001001', 'DESCENT', 'A submersible drops through black water toward the liner’s broken bow.', 'NARRATOR: Below the surface, time has no shoreline.', 60, 120, 60, '{"role":"beat","dataset":"LOCAL DEMO · TITANIC","parent_scene":"01","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 01:00:01', 3, 'UTC')),
    ('41101010-1010-1010-1010-000100000003', 'beat', 'WRECK', 8, 'Script', 'understood', 'demo-feature', 'rev-05', '01', 3, '40101010-1010-1010-1010-000000001001', 'WRECK', 'The remote camera passes torn corridors, china, and a silent grand staircase.', 'NARRATOR: Every object keeps the shape of the hand that used it.', 120, 180, 60, '{"role":"beat","dataset":"LOCAL DEMO · TITANIC","parent_scene":"01","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 01:00:02', 3, 'UTC')),
    ('41101010-1010-1010-1010-000100000004', 'beat', 'SAFE', 9, 'Script', 'understood', 'demo-feature', 'rev-05', '01', 4, '40101010-1010-1010-1010-000000001001', 'SAFE', 'A robotic arm opens a battered safe and lifts a damp sketch case.', 'NARRATOR: The ocean gives back one small witness.', 180, 240, 60, '{"role":"beat","dataset":"LOCAL DEMO · TITANIC","parent_scene":"01","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 01:00:03', 3, 'UTC')),
    ('41101010-1010-1010-1010-000100000005', 'beat', 'PORTRAIT', 10, 'Script', 'understood', 'demo-feature', 'rev-05', '01', 5, '40101010-1010-1010-1010-000000001001', 'PORTRAIT', 'A charcoal portrait appears on the monitor; the elderly Rose claims the young woman.', 'ROSE: That is me, before the ship became a story.', 240, 300, 60, '{"role":"beat","dataset":"LOCAL DEMO · TITANIC","parent_scene":"01","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 01:00:04', 3, 'UTC')),
    ('41101010-1010-1010-1010-000200000001', 'beat', 'NAME', 11, 'Script', 'understood', 'demo-feature', 'rev-05', '02', 1, '40101010-1010-1010-1010-000000001002', 'NAME', 'Rose Calvert watches the salvage team search the safe for the Heart of the Ocean.', 'ROSE: My name was Rose DeWitt Bukater then.', 300, 348, 48, '{"role":"beat","dataset":"LOCAL DEMO · TITANIC","parent_scene":"02","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 01:00:05', 3, 'UTC')),
    ('41101010-1010-1010-1010-000200000002', 'beat', 'DRAWING', 12, 'Script', 'understood', 'demo-feature', 'rev-05', '02', 2, '40101010-1010-1010-1010-000000001002', 'DRAWING', 'The crew studies the dated drawing and compares it with the wreck footage.', 'NARRATOR: A face crosses a century intact.', 348, 396, 48, '{"role":"beat","dataset":"LOCAL DEMO · TITANIC","parent_scene":"02","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 01:00:06', 3, 'UTC')),
    ('41101010-1010-1010-1010-000200000003', 'beat', 'DIAMOND', 13, 'Script', 'understood', 'demo-feature', 'rev-05', '02', 3, '40101010-1010-1010-1010-000000001002', 'DIAMOND', 'Brock presses Rose for the diamond’s last known location.', 'BROCK: The stone was on the ship.', 396, 444, 48, '{"role":"beat","dataset":"LOCAL DEMO · TITANIC","parent_scene":"02","storyboard_version":"titanic-v1"}', '{"source":"direct_clickhouse","transport":"sql","adapter":"script-seed","runtime_mode":"simulation"}', toDateTime64('2026-09-08 01:00:07', 3, 'UTC')),
